const initialState={xp:720,xpNext:1000,tokens:125,streak:5,completed:[],started:[],chestsOpened:0,creatures:[],achievements:3};
const quests=[{id:1,title:'Duka av efter middagen',detail:'Kök · cirka 10 min',icon:'dish',color:'green',xp:20,tokens:5,difficulty:'Lätt'},{id:2,title:'Vattna alla blommor',detail:'Trädgård · cirka 15 min',icon:'flower',color:'yellow',xp:25,tokens:6,difficulty:'Mellan'},{id:3,title:'Sortera återvinningen',detail:'Hemma · cirka 10 min',icon:'recycle',color:'blue',xp:15,tokens:4,difficulty:'Lätt'},{id:4,title:'Bädda sängen',detail:'Sovrum · cirka 5 min',icon:'bed',color:'purple',xp:10,tokens:3,difficulty:'Lätt'},{id:5,title:'Hjälp till med middagen',detail:'Kök · cirka 20 min',icon:'carrot',color:'green',xp:35,tokens:8,difficulty:'Mellan'}];
const defaultState=()=>JSON.parse(JSON.stringify(initialState));let state;try{state=JSON.parse(localStorage.getItem('familjeaventyr-state'))||defaultState()}catch{state=defaultState()}const legacyShards=Number(state.shards)||0;state.tokens=(Number(state.tokens)||0)+legacyShards;state.shards=0;if(legacyShards>0){try{localStorage.setItem('familjeaventyr-state',JSON.stringify(state))}catch{}}state.curses=Array.isArray(state.curses)?state.curses:[];state.curses.forEach(c=>{if(c.status==='pending'){c.submittedAt=c.submittedAt||Date.now();c.submittedBy=c.submittedBy||'Alex'}});state.curseHistory=Array.isArray(state.curseHistory)?state.curseHistory:[];state.customQuests=Array.isArray(state.customQuests)?state.customQuests:[];state.questSubmissions=Array.isArray(state.questSubmissions)?state.questSubmissions:[];state.awardedSubmissionIds=Array.isArray(state.awardedSubmissionIds)?state.awardedSubmissionIds:[];state.approvedQuestCount=Number(state.approvedQuestCount)||state.completed.length;state.lastStreakDate=state.lastStreakDate||'';state.notifications=Array.isArray(state.notifications)?state.notifications:[];const starterCreatureNames=new Set(['lumo','mossa','stella']);const previousCreatureCount=Array.isArray(state.creatures)?state.creatures.length:0;state.creatures=(Array.isArray(state.creatures)?state.creatures:[]).filter(c=>!starterCreatureNames.has(String(c.id||'').toLowerCase())&&!starterCreatureNames.has(String(c.name||'').toLowerCase()));const removedStarterCreatures=state.creatures.length!==previousCreatureCount;state.role='player';state.creatures.forEach(c=>{if(c.ready===false&&!c.cooldownUntil&&!c.isCursed)c.ready=true});window.gameState=state;if(removedStarterCreatures){try{localStorage.setItem('familjeaventyr-state',JSON.stringify(state))}catch{}}let currentView='hem',questFilter='Alla',currentRankingPeriod='season';function save(){if(window.demoSandbox?.active){state.tokens=Number.MAX_SAFE_INTEGER;window.demoSandbox.workingState=state;window.gameState=state;return}window.gameState=state;localStorage.setItem('familjeaventyr-state',JSON.stringify(state))}function beginLocalDemo(){const copy=JSON.parse(JSON.stringify(window.gameState||state));copy.role='admin';copy.tokens=Number.MAX_SAFE_INTEGER;state=copy;window.gameState=state;render()}function restoreLocalDemo(snapshot){state=snapshot;window.gameState=state;render()}function demoCoinText(){return window.demoSandbox?.active?'∞':state.tokens}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}function xpPercent(){return Math.min(100,Math.round(state.xp/state.xpNext*100))}function allQuests(){return window.remoteFamily?.familyId?[...state.customQuests]:[...quests,...state.customQuests]}function activeQuests(){return allQuests().filter(q=>!state.completed.includes(q.id))}function latestQuestSubmission(id){return state.questSubmissions.filter(s=>String(s.questId)===String(id)&&(!window.remoteFamily?.familyId||s.userId===window.remoteFamily.member?.user_id)).sort((a,b)=>b.submittedAt-a.submittedAt)[0]}
function questRow(q){const done=state.completed.includes(q.id),started=state.started.includes(q.id),blocked=window.curseBlocksQuests(state),submission=latestQuestSubmission(q.id),pending=submission?.status==='pending_approval',rejected=submission?.status==='rejected',today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),scheduledFuture=Boolean(q.scheduledFor&&q.scheduledFor>today),weekday=q.scheduledFor?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',weekday:'long'}).format(new Date(`${q.scheduledFor}T12:00:00`)):'';const label=done?'Godkänd ✓':pending?'Väntar på klartecken':blocked?'🔒 Vänta':scheduledFuture?`Planerad ${weekday}`:rejected?'Försök igen':window.remoteFamily?.familyId?'Markera som klar':started?'Markera som klar':'Påbörja',statusText=done?'Godkänd':pending?'Väntar på klartecken':blocked?'Låst av aktiv förbannelse':scheduledFuture?`Tillgänglig ${weekday}`:rejected?'Nekad':started?'Påbörjad':'Inte påbörjad';return `<div class="quest-row ${scheduledFuture?'is-scheduled':''}"><div class="quest-icon ${q.color}">${choreIcon(q.icon)}</div><div class="quest-info"><b>${esc(q.title)}</b><span>${q.detail} · ${q.difficulty}</span>${q.scheduledFor?`<small class="quest-status schedule-hint">Planerad: ${weekday}, ${new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',day:'numeric',month:'short'}).format(new Date(`${q.scheduledFor}T12:00:00`))}</small>`:''}${!pending&&!rejected?`<small class="quest-status">${statusText}</small>`:''}${pending?'<small class="quest-status pending-status">Inskickad för godkännande</small>':''}${rejected?`<small class="quest-status rejected-status">Nekad${submission.reason?': '+esc(submission.reason):''} · du kan försöka igen</small>`:''}</div><div class="quest-reward"><b>+${q.xp} XP</b> · ${q.tokens} mynt</div><button class="quest-action ${done?'done':''}" data-quest="${q.id}" ${done||pending||blocked||scheduledFuture?'disabled':''}>${label}</button></div>`}function submitQuest(id){if(window.curseBlocksQuests(state)){toast('Slutför först alla förbannelseuppgifter! ☠');return}const q=allQuests().find(item=>String(item.id)===String(id));if(!q||state.completed.includes(q.id))return;const latest=latestQuestSubmission(q.id);if(latest?.status==='pending_approval')return;const now=Date.now();state.questSubmissions.push({id:`submission-${now}-${Math.random().toString(36).slice(2,6)}`,questId:q.id,questTitle:q.title,submittedBy:window.demoSandbox?.active?(window.remoteFamily?.member?.display_name||'Admin'):'Alex',userId:window.demoSandbox?.active?window.remoteFamily?.member?.user_id:undefined,submittedAt:now,status:'pending_approval',xp:q.xp,tokens:q.tokens});state.started=state.started.filter(x=>Number(x)!==Number(q.id));save();render();toast('Uppgiften väntar nu på en vuxens klartecken.')}
function decideQuestSubmission(id,approver,decision,reason=''){if(state.role!=='admin'){toast('Endast administratörer får fatta beslut.');return}const submission=state.questSubmissions.find(s=>s.id===id&&s.status==='pending_approval');if(!submission)return;if(!String(approver||'').trim()){toast('Välj en administratör som beslutsfattare.');return}submission.status=decision;submission.approver=approver;submission.decidedAt=Date.now();submission.reason=decision==='rejected'?String(reason).trim():'';if(decision==='approved'&&!state.awardedSubmissionIds.includes(submission.id)){state.xp+=submission.xp;state.tokens+=submission.tokens;state.awardedSubmissionIds.push(submission.id);state.completed.push(submission.questId);state.approvedQuestCount+=1;const today=new Date().toLocaleDateString('sv-SE');if(state.lastStreakDate!==today){state.streak+=1;state.lastStreakDate=today}if([1,10,50].includes(state.approvedQuestCount))state.achievements+=1;const companion=state.creatures.find(c=>!c.isCursed);if(companion)companion.creatureXp=(companion.creatureXp||0)+10}state.notifications.push({message:decision==='approved'?`${submission.questTitle} godkändes av ${approver}.`:`${submission.questTitle} nekades${submission.reason?': '+submission.reason:''}`,createdAt:Date.now()});save();render();toast(decision==='approved'?'Uppgiften godkändes · belöningar utdelade!':'Uppgiften nekades. Spelaren kan försöka igen.')}
