 const tasks=allQuests();
 const approvedCount=tasks.filter(q=>state.completed.includes(q.id)||latestQuestSubmission(q.id)?.status==='approved').length;
 const pendingCount=tasks.filter(q=>latestQuestSubmission(q.id)?.status==='pending_approval').length;
 const percent=tasks.length?Math.round(approvedCount/tasks.length*100):0;
 const blocked=window.curseBlocksQuests(state);
 const focusIndex=tasks.findIndex(q=>!state.completed.includes(q.id)&&latestQuestSubmission(q.id)?.status!=='approved'&&latestQuestSubmission(q.id)?.status!=='pending_approval'&&!blocked);
 const today=tasks.filter(q=>!state.completed.includes(q.id)&&latestQuestSubmission(q.id)?.status!=='approved');
