window.renderGame=render;window.showToast=toast;
function formatAbilityCountdown(milliseconds){const totalSeconds=Math.max(0,Math.ceil(milliseconds/1000));const days=Math.floor(totalSeconds/86400),hours=Math.floor((totalSeconds%86400)/3600),minutes=Math.floor((totalSeconds%3600)/60),seconds=totalSeconds%60;if(days)return `${days} d ${hours} tim`;if(hours)return `${hours} tim ${minutes} min`;if(minutes)return `${minutes} min ${seconds} sek`;return `${seconds} sek`}
function creaturePowerUi(creature){const definition=creatureDefinition(creature.name)||{},minimum=definition.minLevel||1,now=Date.now(),active=window.remoteFamily?.creatureEffects?.some(effect=>effect.creature_id===creature.id&&effect.uses_remaining>0&&(!effect.expires_at||new Date(effect.expires_at).getTime()>now)),cooldown=creature.cooldownUntil?Number(creature.cooldownUntil)-now:0;if(creature.consumedAt)return{status:'Förbrukad',button:'Förbrukad',className:'is-consumed',disabled:true};if(Number(creature.level||1)<minimum)return{status:`Låses upp på nivå ${minimum}`,button:`Nivå ${minimum}`,className:'is-locked',disabled:true};if(active)return{status:'Aktivt',button:'Aktivt',className:'is-active',disabled:true};if(cooldown>0)return{status:`Vilar · ${formatAbilityCountdown(cooldown)}`,button:`Vilar · ${formatAbilityCountdown(cooldown)}`,className:'is-cooldown',disabled:true};return{status:'Kraften är redo',button:'Använd kraft',className:'is-ready',disabled:false}}
function updateCreaturePowerCountdowns(){document.querySelectorAll('[data-power-button]').forEach(button=>{const creature=window.gameState?.creatures?.find(item=>String(item.id)===button.dataset.powerButton);if(!creature)return;const power=creaturePowerUi(creature),status=document.querySelector(`[data-power-status="${CSS.escape(button.dataset.powerButton)}"]`);button.textContent=power.button;button.disabled=power.disabled;button.classList.remove('is-ready','is-active','is-cooldown','is-consumed','is-locked');button.classList.add(power.className);if(status){status.textContent=power.status;status.classList.remove('is-ready','is-active','is-cooldown','is-consumed','is-locked');status.classList.add(power.className)}})}
setInterval(updateCreaturePowerCountdowns,1000);
